# Strings with arbitrary content, personal identifiers, URLs and key material are not output fields.
NEVER_FIELDS = {'body','body_html','body_text','description','message','title','content','value','secret','token','key','raw_key','public_key','email','login','url','html_url','avatar_url','download_url','browser_download_url','archive_download_url','token_last_eight','credential_id','authorization_id','single_file_name','selected_workflows'}
OPTIONAL_DOMAINS = {'identity','users','teams','billing','api-activity','copilot','network','security','integrations','codespaces','migration','collaboration'}


def wanted(path, op):
    return op['operationId'] in EXACT or any(re.search(p,path) for p in FAMILIES)


def disposition(path, op, hazards, is_planned):
    if hazards: return 'Excluded', 'Retrieval boundary: '+ '; '.join(hazards), None
    if is_planned: return 'Planned', 'Metadata evidence design in collector registry; runtime remains disabled until release gates pass.', 'C1' if op['operationId'] in {'orgs/get','repos/list-for-org','repos/get'} else 'C2'
    if op.get('deprecated') or '-legacy' in op.get('operationId',''): return 'Deferred', 'Legacy/deprecated operation; prefer supported scoped replacement; review removal and migration compatibility in C4.', 'C4'
    if path.startswith(('/gists','/classrooms','/assignments','/marketplace_listing','/emojis','/gitignore','/codes_of_conduct','/zen','/octocat','/feeds')) or path=='/':
        return 'Excluded','Personal, educational, marketplace-provider or static platform content outside enterprise assessment.',None
    if path.startswith(('/user','/users','/notifications','/search','/repositories','/events')):
        return 'Deferred','Requires separately authorized user/global scope or search completeness design; not an enterprise enumeration substitute.', 'C4'
    if any(x in path for x in ['/issues','/pulls','/releases','/commits','/comments','/milestones','/projectsV2','/stacks']):
        return 'Deferred','Collaboration metadata needs reviewed selective GraphQL projection where REST returns bodies, patches or free text; migration-scope and retention review in C3.', 'C3'
    if '/scim/' in path: return 'Deferred','Separate identity engagement: response minimization/SCIM attributes filter, provisioning principal and pseudonym relationships must be verified in C3.', 'C3'
    if 'audit' in path or '/events' in path: return 'Deferred','Sensitive heterogeneous event records need explicit event/field allowlist, retention window and streaming credential review in C3.', 'C3'
    if 'secret-scanning' in path or 'code-scanning' in path or 'dependabot/alerts' in path or 'advisories' in path:
        return 'Deferred','Restricted security details require dedicated response and PII/content review before safe aggregate collection in C3.', 'C3'
    if 'reports' in path or '/exports/' in path: return 'Deferred','Report/signed URL lifecycle needs a separately scoped download policy and retention review; no automatic download.', 'C4'
    return 'Deferred','Additional detail or adjacent capability beyond current metadata plan; verify response projection, discovery IDs and incremental value in C4.', 'C4'

